{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "https://raw.githubusercontent.com/rfordatascience/tidytuesday/master/data/2022/2022-06-21/ds_salaries.csv"
  },
  "transform": [
    {
      "aggregate": [{"op": "average", "field": "salary_in_usd", "as": "average_salary"}],
      "groupby": ["work_year"]
    }
  ],
  "width": "container",
  "height": 300,
  "mark": {
    "type": "line",
    "point": true,
    "tooltip": true
  },
  "encoding": {
    "x": {
      "field": "work_year",
      "type": "ordinal",
      "title": "年份 (Year)"
    },
    "y": {
      "field": "average_salary",
      "type": "quantitative",
      "title": "平均年薪 (美元)",
      "axis": {"format": "$,.0f"}
    },
    "tooltip": [
      {"field": "work_year", "title": "年份"},
      {"field": "average_salary", "title": "平均年薪 (美元)", "format": "$,.0f"}
    ]
  },
  "config": {
    "axis": {"grid": true, "gridDash": [2,2]},
    "view": {"stroke": "transparent"}
  }
}

