{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "ds_salaries.csv"
  },
  "transform": [
    {
      "calculate": "datum.experience_level === 'EN' ? 1 : datum.experience_level === 'MI' ? 2 : datum.experience_level === 'SE' ? 3 : 4",
      "as": "experience_level_num"
    },
    {
      "calculate": "datum.company_size === 'S' ? 1 : datum.company_size === 'M' ? 1.25 : 1.5",
      "as": "company_size_num"
    },
    {
      "calculate": "datum.experience_level_num * datum.company_size_num",
      "as": "company_employee_strength"
    },
    {
      "calculate": "datum.employment_type === 'FT' ? 1 : datum.employment_type === 'PT' ? 2 : datum.employment_type === 'CT' ? 3 : 4",
      "as": "employment_type_num"
    }
  ],
  "mark": "point",
  "encoding": {
    "x": {
      "field": "employment_type_num",
      "type": "quantitative",
      "title": "Employment Type (Encoded)"
    },
    "y": {
      "field": "company_employee_strength",
      "type": "quantitative",
      "title": "Company-Employee Strength"
    },
    "size": {
      "field": "salary_in_usd",
      "type": "quantitative",
      "title": "Salary in USD"
    },
